UserEmail.isValidationPending = async (uid, email) => {
	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return false;
	}

	const [ttlMs, confirmObj] = await Promise.all([
		db.pttl(`confirm:byUid:${uid}`),
		db.getObject(`confirm:${code}`),
	]);
	return !!(ttlMs > 0 && confirmObj && confirmObj.email &&
		String(confirmObj.uid) === String(uid) &&
		(!email || email.toLowerCase() === confirmObj.email.toLowerCase()));
};

UserEmail.expireValidation = async (uid) => {
	const code = await db.get(`confirm:byUid:${uid}`);
	const keys = [`confirm:byUid:${uid}`];
	if (code) {
		keys.push(`confirm:${code}`);
	}
	await db.deleteAll(keys);
};

UserEmail.getValidationExpiry = async (uid) => {
	if (!(await UserEmail.isValidationPending(uid))) {
		return null;
	}
	const ttlMs = await db.pttl(`confirm:byUid:${uid}`);
	const expiryMs = meta.config.emailConfirmExpiry * 24 * 60 * 60 * 1000;
	return ttlMs > 0 ? Math.min(ttlMs, expiryMs) : null;
};

UserEmail.canSendValidation = async (uid, email) => {
	if (!(await UserEmail.isValidationPending(uid, email))) {
		return true;
	}
	const ttlMs = await UserEmail.getValidationExpiry(uid);
	if (ttlMs === null) {
		return true;
	}
	const intervalMs = meta.config.emailConfirmInterval * 60 * 1000;
	const expiryMs = meta.config.emailConfirmExpiry * 24 * 60 * 60 * 1000;
	return ttlMs + intervalMs < expiryMs;
};

